/* ---------------- Platform-level config ---------------- */
/* Login único: a sessão é a do Dashboard Financeiro (cookie HttpOnly). Nenhuma senha fica no navegador. */

/* Storage wrapper usado só para a "sessão de login" (algo por dispositivo,
   não precisa ser compartilhado). Cai para memória se o navegador bloquear
   localStorage. */
let storageIsPersistent = true;
const storage = (function(){
  try{
    const k = '__clubn_test__';
    window.localStorage.setItem(k, '1');
    window.localStorage.removeItem(k);
    return window.localStorage;
  } catch(e){
    storageIsPersistent = false;
    const mem = {};
    return {
      getItem: k => (k in mem ? mem[k] : null),
      setItem: (k,v) => { mem[k] = String(v); },
      removeItem: k => { delete mem[k]; }
    };
  }
})();

/* ---------------- Dados compartilhados (Calls, Propostas, Diagnósticos) ----------------
   Agora vivem num banco de dados de verdade (Postgres), acessado por uma API
   própria (server.js). Para o resto do app continuar simples e rápido, uma
   cópia em memória (cache) é mantida localmente: leituras são instantâneas,
   e cada escrita atualiza o cache na hora e envia a mudança pro servidor em
   segundo plano. Se o servidor estiver fora do ar, a tela avisa o usuário. */
const API_BASE = '';
let apiIsAvailable = true;
let _callsCache = [];
let _propostasCache = [];
let _diagnosticosCache = [];
let _apresentacoesCache = [];

function renderStorageWarningBanner(){
  if(apiIsAvailable) return '';
  return `
    <div class="storage-warning-banner">
      ⚠️ Não foi possível conectar ao servidor/banco de dados agora. Você pode continuar navegando, mas o que for criado ou alterado nesta sessão <strong>pode não ser salvo</strong> até a conexão voltar. Recarregue a página em alguns instantes, ou avise o responsável se o problema continuar.
    </div>
  `;
}

function sessionExpired(){
  /* sessão do Dashboard expirou: volta para o login (na janela principal) */
  try{ window.parent.postMessage({type:'funil:session-expired'}, location.origin); } catch(e){}
  try{ if(window.top === window) location.href = '/'; } catch(e){}
}
async function apiRequest(method, path, body){
  try{
    const res = await fetch(API_BASE + path, {
      method,
      credentials: 'same-origin',
      headers: body !== undefined ? {'Content-Type':'application/json'} : undefined,
      body: body !== undefined ? JSON.stringify(body) : undefined
    });
    if(res.status === 401 || res.status === 403){ sessionExpired(); return null; }
    if(!res.ok) throw new Error('HTTP ' + res.status);
    apiIsAvailable = true;
    if(method !== 'GET') funilNotifyChange();
    return await res.json();
  } catch(e){
    console.error('Falha de comunicação com o servidor:', e);
    apiIsAvailable = false;
    alert('Não foi possível salvar essa alteração no banco de dados agora (falha de conexão com o servidor). Verifique sua internet e tente de novo — se persistir, o serviço pode estar fora do ar.');
    return null;
  }
}

async function bootstrapData(){
  try{
    const res = await fetch(API_BASE + '/api/funil/bootstrap', {credentials:'same-origin'});
    if(res.status === 401 || res.status === 403){ sessionExpired(); return; }
    if(!res.ok) throw new Error('HTTP ' + res.status);
    const data = await res.json();
    _callsCache = data.calls || [];
    _propostasCache = data.propostas || [];
    _diagnosticosCache = data.diagnosticos || [];
    _apresentacoesCache = data.apresentacoes || [];
    if(data.operator && data.operator.name) OPERATOR_NAME = data.operator.name;
    apiIsAvailable = true;
  } catch(e){
    console.error('Falha ao carregar dados iniciais do servidor:', e);
    apiIsAvailable = false;
  }
}

function escapeHtml(str){
  return String(str == null ? '' : str)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function fmtDatePt(iso){
  try{
    const d = new Date(iso);
    return d.toLocaleDateString('pt-BR') + ' às ' + d.toLocaleTimeString('pt-BR', {hour:'2-digit', minute:'2-digit'});
  } catch(e){ return ''; }
}

/* ---------------- Diagnósticos ---------------- */
function loadDiagnostics(){
  return _diagnosticosCache;
}
function addDiagnosticRecord(record){
  _diagnosticosCache.unshift(record);
  apiRequest('POST', '/api/funil/diagnosticos', record);
  return true;
}

/* ---------------- Calls / reuniões (CRM) ---------------- */
function loadCalls(){
  return _callsCache;
}
function addCall(call){
  _callsCache.push(call);
  apiRequest('POST', '/api/funil/calls', call);
  return true;
}
function updateCall(id, patch){
  const idx = _callsCache.findIndex(c => c.id === id);
  if(idx > -1){
    _callsCache[idx] = Object.assign({}, _callsCache[idx], patch);
    apiRequest('PUT', '/api/funil/calls/' + encodeURIComponent(id), patch);
    return true;
  }
  return false;
}
function deleteCall(id){
  _callsCache = _callsCache.filter(c => c.id !== id);
  apiRequest('DELETE', '/api/funil/calls/' + encodeURIComponent(id));
  return true;
}

/* ---------------- Propostas (CRM) ---------------- */
function loadPropostas(){
  return _propostasCache;
}
function addProposta(proposta){
  _propostasCache.push(proposta);
  apiRequest('POST', '/api/funil/propostas', proposta);
}
function updateProposta(id, patch){
  const idx = _propostasCache.findIndex(p => p.id === id);
  if(idx > -1){
    _propostasCache[idx] = Object.assign({}, _propostasCache[idx], patch);
    apiRequest('PUT', '/api/funil/propostas/' + encodeURIComponent(id), patch);
  }
}
function deleteProposta(id){
  _propostasCache = _propostasCache.filter(p => p.id !== id);
  apiRequest('DELETE', '/api/funil/propostas/' + encodeURIComponent(id));
}

/* ---------------- Apresentações (telas enviadas em PNG) ---------------- */
