/* Redimensiona/recomprime uma imagem enviada antes de guardar no localStorage,
   já que fotos e screenshots direto do celular podem ter vários MB e estourar
   a cota de armazenamento do navegador (geralmente ~5-10MB no total). */
function compressImageFile(file, maxDim, quality, callback){
  maxDim = maxDim || 1600;
  quality = quality || 0.82;
  const reader = new FileReader();
  reader.onload = function(ev){
    const img = new Image();
    img.onload = function(){
      let w = img.naturalWidth, h = img.naturalHeight;
      if(w > maxDim || h > maxDim){
        if(w >= h){ h = Math.round(h * maxDim / w); w = maxDim; }
        else { w = Math.round(w * maxDim / h); h = maxDim; }
      }
      try{
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);
        callback(canvas.toDataURL('image/jpeg', quality));
      } catch(e){
        console.error(e);
        callback(ev.target.result);
      }
    };
    img.onerror = function(){ callback(null); };
    img.src = ev.target.result;
  };
  reader.onerror = function(){ callback(null); };
  reader.readAsDataURL(file);
}

