/* ---------------- Apresentação da solução (presenter-driven, sem IA) ---------------- */
function startPresentation(){
  const overlay = document.getElementById('loadingOverlay');
  if(overlay.style.display === 'flex') return; /* evita iniciar duas vezes (toque duplo) */
  const textEl = document.getElementById('loadingText');
  const fill = document.getElementById('loadingBarFill');
  const messages = ['Compilando dados','Avaliando','Processando dados','Gerando apresentação'];
  overlay.style.display = 'flex';
  fill.style.width = '0%';
  void fill.offsetWidth;
  requestAnimationFrame(()=>{ fill.style.width = '100%'; });
  let i = 0;
  textEl.textContent = messages[0];
  const msgInterval = setInterval(()=>{
    i++;
    if(i < messages.length){
      textEl.style.opacity = 0;
      setTimeout(()=>{ textEl.textContent = messages[i]; textEl.style.opacity = 1; }, 150);
    }
  }, 1250);
  setTimeout(()=>{
    clearInterval(msgInterval);
    overlay.style.display = 'none';
    appState.view = 'presentation';
    appState.presentationSlide = 0;
    appState.presentationStage = null;
    appState.presentationWaLink = null;
    render();
  }, 5000);
}

const PRES_IMAGES = {
  slide1: 'data:image/jpeg;base64,',
  slide2: 'data:image/jpeg;base64,',
  slide3: 'data:image/jpeg;base64,',
  slide4: 'data:image/jpeg;base64,',
  slide5: 'data:image/jpeg;base64,',
  slide6: 'data:image/jpeg;base64,',
  slide7: 'data:image/jpeg;base64,',
  slide8: 'data:image/jpeg;base64,',
  slide9: 'data:image/jpeg;base64,',
  slideProposito: 'data:image/png;base64,',
};


function presentationSlides(){
  const objetivosText = (state.objetivos && state.objetivos.length) ? state.objetivos.join(', ') : 'Objetivos do diagnóstico';
  const slide3Image = state.customSlide3Image || PRES_IMAGES.slide3;
  const relData = buildRelatorioData();
  /* Telas da apresentação escolhida na call; sem escolha, as telas padrão Club'n. */
  const apres = state.selectedApresentacao;
  const middle = (apres && apres.telas && apres.telas.length)
    ? apres.telas.map(img => ({ image: img }))
    : [
      { image: PRES_IMAGES.slide2 },
      { image: slide3Image },
      { image: PRES_IMAGES.slide4 },
      { image: PRES_IMAGES.slide5 },
      { image: PRES_IMAGES.slide6 },
      { image: PRES_IMAGES.slide7 },
      { image: PRES_IMAGES.slide8, nextLabel:'Faz sentido!' },
      { image: PRES_IMAGES.slideProposito },
      { image: PRES_IMAGES.slide9 }
    ];
  const slides = [
    { type:'slide1custom', objetivosText, pctTotal: relData.pctTotal, novasIndicacoes: relData.novasIndicacoes },
    ...middle,
    { type:'resultado',
      nomeCliente: state.nomeCliente,
      nomeEmpresa: state.nomeEmpresa,
      faturamentoAtual: relData.faturamentoMensal,
      pctTotal: relData.pctTotal,
      faturamentoMeta: relData.faturamentoMensal + relData.valorMensalTotal,
      acumulado12: relData.acumulado12Total
    }
  ];

  // Propostas selecionadas para esta call: suas telas entram em sequência,
  // logo após "Qual resultado esperado?".
  (state.selectedPropostas || []).forEach(p=>{
    if(p.tela1ImageDataUrl) slides.push({ image: p.tela1ImageDataUrl });
    if(p.tela2ImageDataUrl) slides.push({ image: p.tela2ImageDataUrl });
    if(p.telaOfertaImageDataUrl) slides.push({ image: p.telaOfertaImageDataUrl });
  });

  return slides;
}

