function renderPresentation(){
  if(appState.presentationStage === 'sent') return renderPresentationSentStage();
  if(appState.presentationStage === 'termometro') return renderPresentationTermometroStage();

  const slides = presentationSlides();
  const i = Math.min(appState.presentationSlide, slides.length-1);
  const s = slides[i];
  const isLast = i === slides.length - 1;

  let frameInner = '';
  let extraFrameClass = '';
  if(s.type === 'slide1custom'){
    frameInner = renderSlide1Custom(s);
    extraFrameClass = ' pres1-frame';
  } else if(s.type === 'proposito'){
    frameInner = renderSlideProposito();
    extraFrameClass = ' pres1-frame';
  } else if(s.type === 'resultado'){
    frameInner = renderSlideResultado(s);
    extraFrameClass = ' pres1-frame';
  } else {
    frameInner = `<img class="pres3-img" src="${s.image}" alt="Slide ${i+1}">`;
  }

  const nextLabel = isLast ? 'Enviar PDF ao cliente' : (s.nextLabel || 'PRÓXIMO »');

  return `
    <div class="pres2-wrap">
      <a href="#" class="back-link pres2-back" id="backToDashboardPres">← Painel</a>
      <div class="pres3-frame${extraFrameClass}">
        ${frameInner}
      </div>
      <div class="pres2-nav">
        <button class="pres2-back-btn" id="presBack" ${i===0?'disabled':''}>←</button>
        <div class="pres2-dots">${slides.map((_,idx)=>`<span class="pres2-dot${idx===i?' active':''}"></span>`).join('')}</div>
        <button class="pres2-next-btn" id="presNext">${nextLabel}</button>
      </div>
    </div>
  `;
}

