/* Inicia o diagnóstico a partir de uma Call já cadastrada: nome do cliente e da
   empresa já são conhecidos, então o chat pula direto para o segmento. */
function startCallDiagnostic(profileId){
  const call = loadCalls().find(c => c.id === appState.activeCallId);
  updateCall(appState.activeCallId, {status:'em_andamento'});
  if(call) document.title = 'Call · ' + (call.nomeEmpresa || call.nomeCliente || 'Funil de Vendas');
  const allPropostas = loadPropostas();
  const selectedPropostas = call && call.propostasSelecionadas && call.propostasSelecionadas.length
    ? allPropostas.filter(p => call.propostasSelecionadas.includes(p.id))
    : [];
  state = {
    step: 0,
    profileId: profileId || 'valor',
    nomeCliente: call ? call.nomeCliente : '',
    nomeEmpresa: call ? call.nomeEmpresa : '',
    segmento:'', subSegmento:'', segmentosSelecionados:[],
    baseAtiva:0, faturamentoMensal:0, ticketMedio:0,
    objetivos:[],
    curvaA:0, curvaB:0, curvaC:0,
    giftbackValor:100, compraMinima:300, dor1Stage:'narrative',
    customSlide3Image: call && call.slide3ImageDataUrl ? call.slide3ImageDataUrl : null,
    selectedPropostas,
    selectedApresentacao: call && call.apresentacaoId ? (loadApresentacoes().find(a => a.id === call.apresentacaoId) || null) : null,
    chat: { transcript: [], fieldIndex: 1, awaitingConfirm:false, typing:false, multiSelectBuffer:[], noClientsBranch:false, dor1ChatStage:null, meetingStage:'narrating' }
  };
  appState.view = 'wizard';
  render();
  startMeetingIntro();
}

function startMeetingIntro(){
  const c = state.chat;
  const blocks = [
    `Olá, <em>${state.nomeCliente}</em>! Vamos começar com o Diagnóstico da <em>${state.nomeEmpresa}</em>.`,
    `Hoje a <em>${state.nomeEmpresa}</em> se enquadra melhor em qual segmento?`
  ];
  playAiSequence(blocks, ()=>{
    c.meetingStage = 'segmento';
    render();
  });
}

function meetingSegmentoOptions(){
  return state.profileId === 'esthetics' ? ESTHETICS_SEGMENTO_OPTIONS : Object.keys(SEGMENTOS);
}

function toggleMeetingMultiselect(value){
  const buf = state.chat.multiSelectBuffer;
  const idx = buf.indexOf(value);
  if(idx > -1) buf.splice(idx,1); else buf.push(value);
  render();
}

function confirmMeetingSegmento(){
  const c = state.chat;
  if(!c.multiSelectBuffer.length) return;
  const selected = c.multiSelectBuffer.slice();
  c.multiSelectBuffer = [];
  state.segmentosSelecionados = selected;
  if(state.profileId === 'esthetics'){
    state.segmento = 'Clínicas, estética e salões';
    state.subSegmento = selected.join(', ');
  } else {
    state.segmento = selected[0];
  }
  proceedChat(selected.join(', '), ()=>{
    pushAi('Perfeito. Agora informe a base ativa de clientes! Pode ser aproximado.');
    c.meetingStage = 'baseAtiva';
  });
}

function submitMeetingBaseAtiva(rawValue){
  const val = parseBRNumber(rawValue);
  if(!val || val<=0) return;
  const c = state.chat;
  proceedChat(fmtInt(val)+' clientes', ()=>{
    state.baseAtiva = val;
    pushAi('Perfeito! Qual o faturamento médio mensal?');
    c.meetingStage = 'faturamento';
  });
}

function submitMeetingFaturamento(rawValue){
  const val = parseBRNumber(rawValue);
  if(!val || val<=0) return;
  const c = state.chat;
  proceedChat(fmtBRL(val), ()=>{
    state.faturamentoMensal = val;
    pushAi(`Qual a maior dor, <em>${state.nomeCliente}</em>? Pode selecionar mais de uma.`);
    c.meetingStage = 'objetivos';
  });
}

function confirmMeetingObjetivos(){
  const c = state.chat;
  if(!c.multiSelectBuffer.length) return;
  const selected = c.multiSelectBuffer.slice();
  c.multiSelectBuffer = [];
  state.objetivos = selected;
  proceedChat(selected.join(', '), ()=>{
    pushAi('Vamos perguntar: qual o ticket médio hoje?');
    c.meetingStage = 'ticketMedio';
  });
}

function submitMeetingTicketMedio(rawValue){
  const val = parseBRNumber(rawValue);
  if(!val || val<=0) return;
  const c = state.chat;
  proceedChat(fmtBRL(val), ()=>{
    state.ticketMedio = val;
    c.transcript.push({type:'resumoCard', data:{
      baseAtiva: state.baseAtiva,
      ticketMedio: state.ticketMedio,
      faturamentoMensal: state.faturamentoMensal,
      objetivos: state.objetivos
    }});
    c.meetingStage = 'confirmGenerate';
  });
}

function runMeetingLoading(onDone){
  const overlay = document.getElementById('loadingOverlay');
  if(overlay.style.display === 'flex') return; /* evita iniciar duas vezes (toque duplo) */
  const textEl = document.getElementById('loadingText');
  const fill = document.getElementById('loadingBarFill');
  const messages = ['Avaliando','Processando dados','Gerando diagnóstico'];
  overlay.style.display = 'flex';
  fill.style.width = '0%';
  void fill.offsetWidth;
  requestAnimationFrame(()=>{ fill.style.width = '100%'; });
  let i = 0;
  textEl.textContent = messages[0];
  const msgInterval = setInterval(()=>{
    i++;
    if(i < messages.length){
      textEl.style.opacity = 0;
      setTimeout(()=>{ textEl.textContent = messages[i]; textEl.style.opacity = 1; }, 150);
    }
  }, 1600);
  setTimeout(()=>{
    clearInterval(msgInterval);
    overlay.style.display = 'none';
    onDone();
  }, 5000);
}

function confirmGenerateDiagnostic(){
  runMeetingLoading(()=>{
    calcCurvas();
    showDiagnostico4Frentes();
  });
}

