function buildRelatorioData(){
  const ind = calcIndicacoes();
  const gm = calcGiftbackMensal();
  const baseFiel = state.curvaA + state.curvaB;
  const indicacoesPct = state.faturamentoMensal ? (ind.incrementoIndicacoes/state.faturamentoMensal*100) : 0;
  const valorMensalTotal = gm.faturamentoMensalRecorrente + ind.incrementoIndicacoes;
  const pctTotal = state.faturamentoMensal ? (valorMensalTotal/state.faturamentoMensal*100) : 0;
  const acumulado12Total = valorMensalTotal*12;
  return {
    nomeCliente: state.nomeCliente,
    nomeEmpresa: state.nomeEmpresa,
    dataStr: new Date().toLocaleDateString('pt-BR'),
    faturamentoMensal: state.faturamentoMensal,
    baseAtiva: state.baseAtiva,
    curvaA: state.curvaA,
    curvaB: state.curvaB,
    baseFiel,
    giftbackMensal: gm.faturamentoMensalRecorrente,
    giftbackPct: gm.pctIncremento,
    novasIndicacoes: ind.novasIndicacoes,
    indicacoesValor: ind.incrementoIndicacoes,
    indicacoesPct,
    pctTotal,
    valorMensalTotal,
    acumulado12Total
  };
}

