function setStepper(activeIdx){
  const block = document.getElementById('stepperBlock');
  if(block) block.style.display = (appState.view==='wizard' && activeIdx > 0) ? 'block' : 'none';
  const seg = document.querySelectorAll('#stepper .seg');
  const labels = document.querySelectorAll('#stepperLabels span');
  seg.forEach((el,i)=>{
    el.classList.remove('done','active');
    if(i < activeIdx) el.classList.add('done');
    else if(i === activeIdx) el.classList.add('active');
  });
  labels.forEach((el,i)=> el.classList.toggle('on', i===activeIdx));
}

function updateTopbarChrome(){
  const tagEl = document.getElementById('topbarTag');
  const logoutBtn = document.getElementById('logoutBtn');
  if(!tagEl || !logoutBtn) return;
  if(appState.view === 'login'){
    tagEl.textContent = 'Plataforma de Diagnóstico';
    logoutBtn.style.display = 'none';
  } else if(appState.view === 'dashboard'){
    tagEl.textContent = 'Plataforma de Diagnóstico';
    logoutBtn.style.display = 'inline-flex';
  } else if(appState.view === 'callForm' || appState.view === 'callProfileChoice' || appState.view === 'propostaForm' || appState.view === 'propostasList' || appState.view === 'callsHistory' || appState.view === 'callEdit'){
    tagEl.textContent = 'CRM de Leads em Reunião';
    logoutBtn.style.display = 'inline-flex';
  } else if(appState.view === 'wizard'){
    tagEl.textContent = currentProfile().name;
    logoutBtn.style.display = 'inline-flex';
  } else if(appState.view === 'history'){
    tagEl.textContent = 'Histórico · ' + currentProfile().name;
    logoutBtn.style.display = 'inline-flex';
  } else if(appState.view === 'presentation'){
    tagEl.textContent = 'Apresentação da Solução';
    logoutBtn.style.display = 'inline-flex';
  }
}

/* ---------------- Loading transition ---------------- */
function goToStep(nextStep, computeFn){
  const overlay = document.getElementById('loadingOverlay');
  const textEl = document.getElementById('loadingText');
  const fill = document.getElementById('loadingBarFill');
  overlay.style.display = 'flex';
  fill.style.width = '0%';
  void fill.offsetWidth;
  requestAnimationFrame(()=>{ fill.style.width = '100%'; });

  let i = 0;
  textEl.textContent = LOADING_MESSAGES[0];
  const msgInterval = setInterval(()=>{
    i++;
    if(i < LOADING_MESSAGES.length){
      textEl.style.opacity = 0;
      setTimeout(()=>{ textEl.textContent = LOADING_MESSAGES[i]; textEl.style.opacity = 1; }, 150);
    }
  }, 1250);

  setTimeout(()=>{
    clearInterval(msgInterval);
    overlay.style.display = 'none';
    if(computeFn) computeFn();
    state.step = nextStep;
    render();
    window.scrollTo({top:0, behavior:'instant'});
  }, 5000);
}

/* ---------------- Calculations ---------------- */
function calcCurvas(){
  const pct = SEGMENTOS[state.segmento] ?? 0.10;
  state.curvaA = Math.round(state.baseAtiva * pct);
  state.curvaB = Math.round(state.baseAtiva * 0.30);
  state.curvaC = state.baseAtiva - state.curvaA - state.curvaB;
  state.segPct = pct;
  // Ticket médio não é mais perguntado — é estimado a partir do faturamento
  // médio mensal dividido pela base ativa de clientes.
  state.ticketMedio = state.baseAtiva ? (state.faturamentoMensal / state.baseAtiva) : 0;
}

function calcDiagnostico(){
  return {
    pctA: state.baseAtiva ? (state.curvaA/state.baseAtiva*100) : 0,
    pctB: state.baseAtiva ? (state.curvaB/state.baseAtiva*100) : 0,
    pctC: state.baseAtiva ? (state.curvaC/state.baseAtiva*100) : 0,
    fatiaA: state.faturamentoMensal*0.40,
    fatiaB: state.faturamentoMensal*0.40,
    fatiaC: state.faturamentoMensal*0.20,
  };
}

function isDor1(){
  // Qualquer dor selecionada usa a mesma sequência interativa de diagnóstico
  // (Programa de Indicações + Giftback, narrado dentro da conversa).
  return !!(state.objetivos && state.objetivos.length);
}

function calcIndicacoes(){
  if(isDor1()){
    // Dor 1: pitch simplificado usando só a Curva A (clientes fiéis).
    const funilTotal = state.curvaA*3;
    const novasIndicacoes = funilTotal*0.30;
    const incrementoIndicacoes = novasIndicacoes*state.ticketMedio;
    return {
      convertingA: state.curvaA, convertingB:0, convertingC:0,
      leadsA: funilTotal, leadsB:0, leadsC:0,
      totalIndicacoes: funilTotal,
      faturamentoTotalIndicacoes: funilTotal*state.ticketMedio,
      incrementoIndicacoes,
      novosClientes: novasIndicacoes,
      funilTotal, novasIndicacoes,
      isDor1: true
    };
  }
  const convertingA = state.curvaA*0.40;
  const convertingB = state.curvaB*0.15;
  const convertingC = state.curvaC*0.05;
  const leadsA = convertingA*3;
  const leadsB = convertingB*3;
  const leadsC = convertingC*3;
  const totalIndicacoes = leadsA+leadsB+leadsC;
  const faturamentoTotalIndicacoes = totalIndicacoes*state.ticketMedio;
  const incrementoIndicacoes = faturamentoTotalIndicacoes*0.30;
  const novosClientes = totalIndicacoes*0.30;
  return {convertingA,convertingB,convertingC,leadsA,leadsB,leadsC,totalIndicacoes,faturamentoTotalIndicacoes,incrementoIndicacoes,novosClientes,isDor1:false};
}

function calcGiftback(){
  const ativaGiftback = state.baseAtiva*0.20;
  const receitaIndividual = state.giftbackValor*4;
  const faturamentoTotal = receitaIndividual*ativaGiftback;
  return {ativaGiftback, receitaIndividual, faturamentoTotal};
}

/* O percentual de incremento do Giftback sobre o faturamento agora é fixo em
   23,78% — uma visão mais realista e consistente, baseada em referência de
   mercado, em vez de variar conforme o cálculo da base de clientes. */
const GIFTBACK_PCT_FIXED = 23.78;
function calcGiftbackMensal(){
  const baseFiel = state.curvaA + state.curvaB;
  const ativaGiftbackMensal = baseFiel*0.20;
  const receitaIndividual = state.giftbackValor*4;
  const pctIncremento = GIFTBACK_PCT_FIXED;
  const faturamentoMensalRecorrente = state.faturamentoMensal * (GIFTBACK_PCT_FIXED/100);
  const acumulado12 = faturamentoMensalRecorrente*12;
  return {baseFiel, ativaGiftbackMensal, receitaIndividual, faturamentoMensalRecorrente, pctIncremento, acumulado12};
}

function calcFinal(){
  const ind = calcIndicacoes();
  const gb = calcGiftback();
  const incrementoTotal = ind.incrementoIndicacoes + gb.faturamentoTotal;
  const faturamentoMes2 = state.faturamentoMensal + incrementoTotal;
  const pctAcrescimo = state.faturamentoMensal ? (incrementoTotal/state.faturamentoMensal*100) : 0;
  // Percentual que o Giftback sozinho representa sobre o faturamento médio mensal — o destaque principal do relatório
  const giftbackPct = state.faturamentoMensal ? (gb.faturamentoTotal/state.faturamentoMensal*100) : 0;
  // Acumulado em 12 meses considera apenas a repetição da ação de Giftback
  const acumulado12Giftback = gb.faturamentoTotal*12;
  return {ind, gb, incrementoTotal, faturamentoMes2, pctAcrescimo, giftbackPct, acumulado12Giftback};
}

/* ---------------- Charts (donut) ---------------- */
const CURVE_COLORS = { a:'#24405f', b:'#4b7a9c', c:'#8b8f95' };

function donutSVG(segments, size){
  size = size || 148;
  const r = 50, cx = 60, cy = 60, strokeW = 16;
  const circumference = 2*Math.PI*r;
  const total = segments.reduce((sum,s)=> sum + s.value, 0) || 1;
  let offsetAccum = 0;
  const circles = segments.map(s=>{
    const frac = s.value/total;
    const dash = frac*circumference;
    const gap = circumference-dash;
    const circle = `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${s.color}" stroke-width="${strokeW}" stroke-dasharray="${dash} ${gap}" stroke-dashoffset="${-offsetAccum}" transform="rotate(-90 ${cx} ${cy})"/>`;
    offsetAccum += dash;
    return circle;
  }).join('');
  return `<svg viewBox="0 0 120 120" width="${size}" height="${size}" style="display:block;">${circles}</svg>`;
}

function chartLegend(segments, formatValue){
  const total = segments.reduce((sum,s)=> sum + s.value, 0) || 1;
  return `<div class="chart-legend">${segments.map(s=>`
    <div class="chart-legend-item">
      <span class="chart-legend-dot" style="background:${s.color}"></span>
      <span class="chart-legend-label">${s.label}</span>
      <span class="chart-legend-value">${formatValue(s.value)} <span class="chart-legend-pct">(${fmtPct(s.value/total*100)})</span></span>
    </div>
  `).join('')}</div>`;
}

function curvasChartsBlock(){
  const qtySegments = [
    { label:'Curva A · fiéis', value: state.curvaA, color: CURVE_COLORS.a },
    { label:'Curva B · intermediária', value: state.curvaB, color: CURVE_COLORS.b },
    { label:'Curva C · fria', value: state.curvaC, color: CURVE_COLORS.c }
  ];
  const d = calcDiagnostico();
  const revSegments = [
    { label:'Curva A · fiéis', value: d.fatiaA, color: CURVE_COLORS.a },
    { label:'Curva B · intermediária', value: d.fatiaB, color: CURVE_COLORS.b },
    { label:'Curva C · fria', value: d.fatiaC, color: CURVE_COLORS.c }
  ];
  return `
    <div class="chart-row">
      <div class="chart-card">
        <div class="chart-card-title">Representação de quantidade</div>
        <div class="chart-card-body">
          ${donutSVG(qtySegments)}
          ${chartLegend(qtySegments, v => fmtInt(v) + ' clientes')}
        </div>
      </div>
      <div class="chart-card">
        <div class="chart-card-title">Representação de faturamento</div>
        <div class="chart-card-body">
          ${donutSVG(revSegments)}
          ${chartLegend(revSegments, v => fmtBRL(v))}
        </div>
      </div>
    </div>
  `;
}

/* ---------------- Icons ---------------- */
function sparkleSVG(){
  return `<svg viewBox="0 0 30 30" width="30" height="30" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <linearGradient id="sparkleGrad" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" stop-color="var(--blue-1)"/>
        <stop offset="100%" stop-color="var(--blue-2)"/>
      </linearGradient>
    </defs>
    <path d="M11 3 C11.8 8 13 9.2 18 10 C13 10.8 11.8 12 11 17 C10.2 12 9 10.8 4 10 C9 9.2 10.2 8 11 3 Z" fill="url(#sparkleGrad)"/>
    <path d="M21 14 C21.4 16.5 22 17.1 24.5 17.5 C22 17.9 21.4 18.5 21 21 C20.6 18.5 20 17.9 17.5 17.5 C20 17.1 20.6 16.5 21 14 Z" fill="url(#sparkleGrad)"/>
  </svg>`;
}
function arrowSVG(){
  return `<svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M9 6l6 6-6 6" stroke="#fff" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

/* ---------------- Main renderer (login / dashboard / wizard / history) ---------------- */
function render(){
  updateTopbarChrome();
  const warnSlot = document.getElementById('storageWarningSlot');
  if(warnSlot){ warnSlot.innerHTML = renderStorageWarningBanner(); }
  const p = document.getElementById('panel');

  if(appState.view === 'login'){
    setStepper(-1);
    p.innerHTML = renderLogin();
  } else if(appState.view === 'dashboard'){
    setStepper(-1);
    p.innerHTML = renderDashboard();
  } else if(appState.view === 'callForm'){
    setStepper(-1);
    p.innerHTML = renderCallForm();
  } else if(appState.view === 'callProfileChoice'){
    setStepper(-1);
    p.innerHTML = renderCallProfileChoice();
  } else if(appState.view === 'propostaForm'){
    setStepper(-1);
    p.innerHTML = renderPropostaForm();
  } else if(appState.view === 'propostasList'){
    setStepper(-1);
    p.innerHTML = renderPropostasList();
  } else if(appState.view === 'callsHistory'){
    setStepper(-1);
    p.innerHTML = renderCallsHistory();
  } else if(appState.view === 'callEdit'){
    setStepper(-1);
    p.innerHTML = renderCallEdit();
  } else if(appState.view === 'history'){
    setStepper(-1);
    p.innerHTML = renderHistoryDetail();
  } else if(appState.view === 'presentation'){
    setStepper(-1);
    p.innerHTML = renderPresentation();
  } else if(appState.view === 'apresentacoesList'){
    setStepper(-1);
    p.innerHTML = renderApresentacoesList();
  } else if(appState.view === 'apresentacaoForm'){
    setStepper(-1);
    p.innerHTML = renderApresentacaoForm();
  } else if(appState.view === 'callDone'){
    setStepper(-1);
    p.innerHTML = renderCallDone();
  } else {
    // wizard
    setStepper(state.step);
    if(state.step===0) p.innerHTML = withBackLink(renderChatStep(), false);
    if(state.step===1) p.innerHTML = wrapPanel(renderStep1());
    if(state.step===2) p.innerHTML = wrapPanel(renderStep2());
    if(state.step===3) p.innerHTML = wrapPanel(renderStep3());
    if(state.step===4) p.innerHTML = wrapPanel(renderStep4());
    if(state.step===5) p.innerHTML = wrapPanel(renderStep5());
  }

  attachHandlers();
  const activeInput = document.getElementById('chatInput');
  if(activeInput){ activeInput.focus(); }
  if(appState.view === 'wizard'){
    window.scrollTo({top:document.body.scrollHeight, behavior:'smooth'});
  } else {
    window.scrollTo({top:0, behavior:'instant'});
  }
}

function withBackLink(inner, wrapped){
  const link = `<a href="#" class="back-link" id="backToDashboardWizard">← Painel</a>`;
  return wrapped ? inner : `<div class="chat-wrap-outer">${link}${inner}</div>`;
}
function wrapPanel(inner){
  return `<div class="panel"><a href="#" class="back-link" id="backToDashboardWizard">← Painel</a>${inner}</div>`;
}

/* ---------------- Login screen ---------------- */
function renderLogin(){
  return `
    <div class="login-wrap">
      <div class="panel login-panel">
        <h1>Plataforma de Diagnóstico</h1>
        <p class="sub">Acesse com suas credenciais para gerenciar os diagnósticos.</p>
        <div class="field">
          <label>Usuário</label>
          <input type="text" id="loginUser" autocomplete="username" placeholder="Usuário">
        </div>
        <div class="field">
          <label>Senha</label>
          <input type="password" id="loginPass" autocomplete="current-password" placeholder="Senha">
        </div>
        <div class="error-text" id="loginError">Usuário ou senha incorretos.</div>
        <div class="actions" style="justify-content:flex-end;">
          <button class="btn-primary" id="loginBtn">Entrar</button>
        </div>
      </div>
    </div>
  `;
}

/* ---------------- Criar Call ---------------- */
/* ---------------- Menu / navegação do CRM ---------------- */
/* Ícones estilo Lucide (traço fino, 2px), desenhados à mão em SVG inline
   para não depender de nenhuma biblioteca externa. */
function crmIcon(name){
  const common = 'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"';
  const icons = {
    'layout-dashboard': `<rect x="3" y="3" width="7" height="9" rx="1" ${common}/><rect x="14" y="3" width="7" height="5" rx="1" ${common}/><rect x="14" y="12" width="7" height="9" rx="1" ${common}/><rect x="3" y="16" width="7" height="5" rx="1" ${common}/>`,
    'headset': `<path d="M3 13a9 9 0 0 1 18 0" ${common}/><path d="M21 13v4a2 2 0 0 1-2 2h-1" ${common}/><rect x="3" y="13" width="4" height="6" rx="1" ${common}/><rect x="17" y="13" width="4" height="6" rx="1" ${common}/>`,
    'clock': `<circle cx="12" cy="12" r="9" ${common}/><path d="M12 7v5l3 3" ${common}/>`,
    'plus-circle': `<circle cx="12" cy="12" r="9" ${common}/><path d="M12 8v8M8 12h8" ${common}/>`,
    'search': `<circle cx="11" cy="11" r="7" ${common}/><path d="m21 21-4.3-4.3" ${common}/>`,
    'users': `<circle cx="9" cy="8" r="3" ${common}/><path d="M3 20c0-3.3 2.7-6 6-6s6 2.7 6 6" ${common}/><circle cx="17" cy="9" r="2.3" ${common}/><path d="M15.5 14c2.5.3 4.5 2.5 4.5 5.5" ${common}/>`,
    'file-spreadsheet': `<path d="M6 2h9l5 5v13a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2Z" ${common}/><path d="M14 2v5h5" ${common}/><path d="M8 13h8M8 17h8M8 13v6" ${common}/>`,
    'calendar': `<rect x="3" y="4" width="18" height="17" rx="2" ${common}/><path d="M8 2v4M16 2v4M3 9h18" ${common}/>`,
    'instagram': `<rect x="3" y="3" width="18" height="18" rx="5" ${common}/><circle cx="12" cy="12" r="4" ${common}/><circle cx="17.5" cy="6.5" r="1" fill="currentColor"/>`,
    'phone': `<path d="M4 4h4l2 5-2.5 2.5a12 12 0 0 0 6 6L16 15l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 2 6a2 2 0 0 1 2-2Z" ${common}/>`,
    'dollar-sign': `<path d="M12 2v20M17 6.5c0-2-2-3.5-5-3.5s-5 1.5-5 3.5 2 3 5 3.7 5 2 5 3.8-2 3.5-5 3.5-5-1.5-5-3.5" ${common}/>`,
    'trending-up': `<path d="M3 17l6-6 4 4 7-8" ${common}/><path d="M15 6h5v5" ${common}/>`,
    'target': `<circle cx="12" cy="12" r="9" ${common}/><circle cx="12" cy="12" r="5" ${common}/><circle cx="12" cy="12" r="1" fill="currentColor"/>`,
    'thermometer': `<path d="M14 14.76V4a2 2 0 0 0-4 0v10.76a4 4 0 1 0 4 0Z" ${common}/>`,
    'briefcase': `<rect x="3" y="7" width="18" height="13" rx="2" ${common}/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" ${common}/>`,
    'edit3': `<path d="m14 4 6 6L8 22H2v-6Z" ${common}/>`,
    'trash2': `<path d="M4 7h16M9 7V5a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2M6 7l1 13a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2l1-13" ${common}/>`,
    'fire': `<path d="M12 2c2 3-2 4-2 7a4 4 0 0 0 8 0c0-1-.3-2-1-3 1 0 3 2 3 6a8 8 0 0 1-16 0c0-5 4-6 5-9 0 2 1 3 3 2-1-1-1-2 0-3Z" ${common}/>`,
    'cloud': `<path d="M7 18a4.5 4.5 0 0 1-1-8.9A5 5 0 0 1 16 7a4 4 0 0 1 1 7.9" ${common}/><path d="M7 18h9" ${common}/>`,
    'snowflake': `<path d="M12 2v20M4.5 7l15 10M19.5 7l-15 10" ${common}/>`,
    'image': `<rect x="3" y="3" width="18" height="18" rx="2" ${common}/><circle cx="8.5" cy="8.5" r="1.5" fill="currentColor"/><path d="m21 15-5-5L5 21" ${common}/>`,
    'whatsapp': `<path d="M12 2a10 10 0 0 0-8.6 15L2 22l5.2-1.4A10 10 0 1 0 12 2Z" ${common}/><path d="M8.5 8.5c0 4 3 7 7 7 .8 0 1-.3 1-1v-1.3l-2.3-.9-.9 1a6 6 0 0 1-3.5-3.5l1-.9-.9-2.3H8.8c-.7 0-.3.2-.3.9Z" fill="currentColor" stroke="none"/>`
  };
  return `<svg viewBox="0 0 24 24" width="18" height="18">${icons[name] || icons['target']}</svg>`;
}

function renderCrmShell(active, innerHtml){
  const navItems = [
    {key:'dashboard', label:'Início', icon:'layout-dashboard'},
    {key:'callForm', label:'Criar Call', icon:'headset'},
    {key:'callsHistory', label:'Histórico', icon:'clock'},
    {key:'propostaForm', label:'Criar Proposta', icon:'plus-circle'},
    {key:'propostasList', label:'Consultar Proposta', icon:'search'}
  ];
  const navButtons = navItems.map(it => `
    <button class="crmd-nav-item${it.key===active?' active':''}" data-nav="${it.key}">
      <span class="crmd-nav-icon">${crmIcon(it.icon)}</span>
      <span class="crmd-nav-label">${escapeHtml(it.label)}</span>
    </button>
  `).join('');
  const bottomButtons = navItems.map(it => `
    <button class="crmd-bottomnav-item${it.key===active?' active':''}" data-nav="${it.key}">
      ${crmIcon(it.icon)}
      <span>${escapeHtml(it.label)}</span>
    </button>
  `).join('');
  return `
    <div class="crmd-shell">
      <div class="crmd-sidebar">
        <div class="crmd-logo">club'n</div>
        <div class="crmd-nav">${navButtons}</div>
      </div>
      <div class="crmd-main">${innerHtml}</div>
      <div class="crmd-bottomnav">${bottomButtons}</div>
    </div>
  `;
}

function renderApresentacaoChoice(name, selectedId){
  const list = loadApresentacoes();
  const opt = (id, label, sub) => `
    <label class="crmd-checkbox-item">
      <input type="radio" name="${name}" class="${name}" value="${id}" ${(selectedId||'') === id ? 'checked' : ''}>
      <span>${escapeHtml(label)} <span class="val">${escapeHtml(sub)}</span></span>
    </label>`;
  return `<div class="crmd-checkbox-list">
    ${opt('', "Padrão Club'n", 'telas padrão')}
    ${list.map(a => opt(a.id, a.nome, (a.telas||[]).length + ' tela' + ((a.telas||[]).length === 1 ? '' : 's'))).join('')}
  </div>
  ${list.length === 0 ? `<p class="crmd-hint" style="margin-top:8px;">Crie apresentações próprias em "Apresentações".</p>` : ''}`;
}

function renderCallForm(){
  const propostas = loadPropostas();
  const propostasHtml = propostas.length === 0
    ? `<p class="crmd-hint">Nenhuma proposta cadastrada ainda. Crie uma em "Criar Proposta".</p>`
    : `<div class="crmd-checkbox-list">${propostas.map(p => `
        <label class="crmd-checkbox-item">
          <input type="checkbox" class="call-proposta-check" value="${p.id}">
          <span>${escapeHtml(p.nome)} <span class="val">${fmtBRL(p.valorVenda||0)}</span></span>
        </label>
      `).join('')}</div>`;

  const content = `
    <a href="#" class="crmd-back-link" id="backFromCallForm">← Painel</a>
    <h1>Criar Call</h1>
    <p class="sub">Cadastre os dados da próxima reunião.</p>
    <div class="crmd-card">
      <div class="crmd-field">
        <label>${crmIcon('users')} Nome do Cliente</label>
        <input type="text" id="callNomeCliente" placeholder="Nome do cliente">
      </div>
      <div class="crmd-field">
        <label>${crmIcon('briefcase')} Nome da Empresa</label>
        <input type="text" id="callNomeEmpresa" placeholder="Nome da empresa">
      </div>
      <div class="crmd-field">
        <label>${crmIcon('instagram')} @ do Instagram</label>
        <input type="text" id="callInstagram" placeholder="@empresa">
      </div>
      <div class="crmd-row2">
        <div class="crmd-field">
          <label>${crmIcon('calendar')} Data</label>
          <input type="date" id="callData">
        </div>
        <div class="crmd-field">
          <label>${crmIcon('clock')} Horário</label>
          <input type="time" id="callHorario">
        </div>
      </div>
      <div class="crmd-error" id="callFormError">Preencha ao menos o nome do cliente e da empresa.</div>

      <div class="crmd-section-title" style="margin-top:4px;">${crmIcon('image')} Personalizar Tela 3 (opcional)</div>
      <p class="crmd-hint" style="margin-bottom:12px;">Envie uma imagem (16:9) para substituir a Tela 3 padrão nesta call.</p>
      <div class="crmd-field">
        <input type="file" id="callSlide3Image" accept="image/*">
        <div class="crmd-hint" id="callSlide3ImageStatus"></div>
      </div>

      <div class="crmd-section-title">${crmIcon('image')} Apresentação para esta call</div>
      <p class="crmd-hint" style="margin-bottom:12px;">As telas entram depois de "Vamos começar lembrando os seus objetivos" e antes de "Qual resultado esperado?".</p>
      ${renderApresentacaoChoice('call-apres', '')}

      <div class="crmd-section-title">${crmIcon('file-spreadsheet')} Propostas para esta call (opcional)</div>
      <p class="crmd-hint" style="margin-bottom:12px;">As telas das propostas marcadas entram na apresentação, logo após "Qual resultado esperado?".</p>
      ${propostasHtml}

      <div class="crmd-actions" style="justify-content:flex-end; margin-top:22px;">
        <button class="crmd-btn-primary" id="callFormSubmit">Salvar Call</button>
      </div>
    </div>
  `;
  return renderCrmShell('callForm', content);
}

