const NEG_STATUS_PILL_CLASS = {
  'Proposta enviada':'crmd-pill-accent',
  'Follow 1':'crmd-pill-warning',
  'Venda realizada':'crmd-pill-success',
  'Declinada':'crmd-pill-danger'
};
function renderNegStatusBadge(s){
  return `<span class="crmd-pill ${NEG_STATUS_PILL_CLASS[s] || 'crmd-pill-neutral'}">${escapeHtml(s)}</span>`;
}

