const STATUS_PILL_CLASS = {
  pendente:'crmd-pill-neutral',
  em_andamento:'crmd-pill-accent',
  diagnostico_enviado:'crmd-pill-accent',
  proposta_enviada:'crmd-pill-warning',
  concluida:'crmd-pill-success'
};
function renderStatusBadge(status){
  return `<span class="crmd-pill ${STATUS_PILL_CLASS[status] || 'crmd-pill-neutral'}">${escapeHtml(callStatusLabel(status))}</span>`;
}
const TERM_PILL_CLASS = { quente:'crmd-pill-danger', morno:'crmd-pill-warning', frio:'crmd-pill-accent' };
function renderTermometroBadge(t){
  return `<span class="crmd-pill ${TERM_PILL_CLASS[t] || 'crmd-pill-neutral'}">${escapeHtml(t.charAt(0).toUpperCase()+t.slice(1))}</span>`;
}

/* ---------------- Dashboard ---------------- */
function isSameWeek(dateVal, ref){
  const d = new Date(dateVal);
  if(isNaN(d.getTime())) return false;
  const day = ref.getDay() || 7;
  const monday = new Date(ref); monday.setDate(ref.getDate()-day+1); monday.setHours(0,0,0,0);
  const sunday = new Date(monday); sunday.setDate(monday.getDate()+6); sunday.setHours(23,59,59,999);
  return d >= monday && d <= sunday;
}
function isSameMonth(dateVal, ref){
  const d = new Date(dateVal);
  if(isNaN(d.getTime())) return false;
  return d.getFullYear()===ref.getFullYear() && d.getMonth()===ref.getMonth();
}

function renderDashboard(){
  const list = loadDiagnostics();
  const q = dashboardFilterText.trim().toLowerCase();
  const filtered = q
    ? list.filter(d => (d.nomeCliente+' '+d.nomeEmpresa).toLowerCase().includes(q))
    : list;

  const rows = filtered.map(d => `
    <tr>
      <td>${escapeHtml(d.perfil)}</td>
      <td>${escapeHtml(d.nomeCliente)}</td>
      <td>${escapeHtml(d.nomeEmpresa)}</td>
      <td>${escapeHtml(d.segmento)}${d.subSegmento ? ' · '+escapeHtml(d.subSegmento) : ''}</td>
      <td>${fmtDatePt(d.createdAt)}</td>
      <td><button class="btn-ghost btn-sm" data-view-id="${d.id}">Ver</button></td>
    </tr>
  `).join('');

  const allCalls = loadCalls();
  const allPropostas = loadPropostas();
  const now = new Date();

  function callValue(call){
    if(!call.propostasSelecionadas || !call.propostasSelecionadas.length) return 0;
    return call.propostasSelecionadas.reduce((sum, pid)=>{
      const p = allPropostas.find(x => x.id === pid);
      return sum + (p && p.valorVenda ? Number(p.valorVenda) : 0);
    }, 0);
  }

  const upcoming = allCalls
    .filter(c => c.status === 'pendente' || c.status === 'em_andamento')
    .sort((a,b)=> new Date(a.dataISO||0) - new Date(b.dataISO||0));

  const done = allCalls
    .filter(c => c.status && c.status !== 'pendente' && c.status !== 'em_andamento')
    .sort((a,b)=> new Date(b.createdAt||0) - new Date(a.createdAt||0))
    .slice(0,5);

  const quenteCalls = allCalls.filter(c => c.termometro === 'quente');
  const mornoCalls = allCalls.filter(c => c.termometro === 'morno');
  const frioCalls = allCalls.filter(c => c.termometro === 'frio');
  const quenteValor = quenteCalls.reduce((sum,c)=> sum + callValue(c), 0);
  const mornoValor = mornoCalls.reduce((sum,c)=> sum + callValue(c), 0);
  const frioValor = frioCalls.reduce((sum,c)=> sum + callValue(c), 0);

  const callsRealizadas = allCalls.filter(c => c.status && c.status !== 'pendente').length;
  const funilTotalValor = allCalls.reduce((sum,c)=> sum + callValue(c), 0);
  const vendasRealizadas = allCalls.filter(c => c.negociacaoStatus === 'Venda realizada');
  const vendasRealizadasValor = vendasRealizadas.reduce((sum,c)=> sum + callValue(c), 0);

  const monthLabelRaw = now.toLocaleDateString('pt-BR', {month:'short', year:'numeric'});
  const monthLabel = monthLabelRaw.charAt(0).toUpperCase() + monthLabelRaw.slice(1).replace('.','').replace(' de ', '/').replace(' ', '/');

  function dayGroupLabel(iso){
    if(!iso) return 'Sem data definida';
    const d = new Date(iso);
    if(isNaN(d.getTime())) return 'Sem data definida';
    const today = new Date(); today.setHours(0,0,0,0);
    const tomorrow = new Date(today); tomorrow.setDate(today.getDate()+1);
    const dOnly = new Date(d); dOnly.setHours(0,0,0,0);
    const dd = String(d.getDate()).padStart(2,'0');
    const mm = String(d.getMonth()+1).padStart(2,'0');
    if(dOnly.getTime() === today.getTime()) return `Hoje, ${dd}/${mm}`;
    if(dOnly.getTime() === tomorrow.getTime()) return `Amanhã, ${dd}/${mm}`;
    return `${dd}/${mm}`;
  }

  let lastDayLabel = null;
  const upcomingGroupedHtml = upcoming.map(c => {
    const label = dayGroupLabel(c.dataISO);
    let headerHtml = '';
    if(label !== lastDayLabel){
      headerHtml = `<div class="crmd-day-group"><span class="crmd-day-dot"></span>${escapeHtml(label)}</div>`;
      lastDayLabel = label;
    }
    return headerHtml + `
      <div class="crmd-list-row">
        <div>
          <div class="crmd-row-name">${escapeHtml(c.nomeCliente)} <span class="crmd-row-sub">· ${escapeHtml(c.nomeEmpresa)}</span></div>
          <div class="crmd-row-meta">${c.instagram ? '@'+escapeHtml(String(c.instagram).replace(/^@/,'')) + ' · ' : ''}${fmtCallDateTime(c.dataISO) || 'sem horário definido'}</div>
        </div>
        <button class="crmd-btn-ghost" style="padding:8px 14px; min-height:0;" data-start-call="${c.id}">${crmIcon('phone')}</button>
      </div>
    `;
  }).join('');

  const termPillClass = { quente:'crmd-pill-danger', morno:'crmd-pill-warning', frio:'crmd-pill-accent' };
  const doneRowsHtml = done.map(c => `
    <div class="crmd-list-row" style="cursor:pointer;" data-edit-call="${c.id}">
      <div>
        <div class="crmd-row-name">${escapeHtml(c.nomeCliente)} <span class="crmd-row-sub">· ${escapeHtml(c.nomeEmpresa)}</span></div>
        <div class="crmd-row-meta">${fmtDatePt(c.createdAt)}</div>
      </div>
      <div style="display:flex; align-items:center; gap:8px;">
        ${c.termometro ? `<span class="crmd-pill ${termPillClass[c.termometro]||'crmd-pill-neutral'}">${c.termometro}</span>` : ''}
        ${c.negociacaoStatus ? `<span class="crmd-pill crmd-pill-accent">${escapeHtml(c.negociacaoStatus)}</span>` : (c.status ? `<span class="crmd-pill crmd-pill-neutral">${escapeHtml(callStatusLabel(c.status))}</span>` : '')}
      </div>
    </div>
  `).join('');

  const diagRows = filtered.map(d => `
    <tr class="clickable" data-view-id="${d.id}">
      <td>${escapeHtml(d.perfil)}</td>
      <td style="color:#fff; font-weight:600;">${escapeHtml(d.nomeCliente)}</td>
      <td>${escapeHtml(d.nomeEmpresa)}</td>
      <td>${escapeHtml(d.segmento)}${d.subSegmento ? ' · '+escapeHtml(d.subSegmento) : ''}</td>
      <td>${fmtDatePt(d.createdAt)}</td>
    </tr>
  `).join('');

  const content = `
    <h1>Funil de Vendas</h1>
    <div class="sub" style="display:flex; align-items:center; gap:7px; font-style:normal;">${crmIcon('calendar')} ${escapeHtml(monthLabel)}</div>

    <div class="crmd-kpi-row">
      <div class="crmd-kpi-card">
        <div class="crmd-kpi-label">Funil Total e Propostas</div>
        <div class="crmd-kpi-value">${fmtBRL(funilTotalValor)}</div>
      </div>
      <div class="crmd-kpi-card success">
        <div class="crmd-kpi-label">Vendas realizadas</div>
        <div class="crmd-kpi-value">${fmtBRL(vendasRealizadasValor)}</div>
      </div>
      <div class="crmd-kpi-card">
        <div class="crmd-kpi-label">Calls realizadas até o momento</div>
        <div class="crmd-kpi-value">${callsRealizadas}</div>
      </div>
    </div>

    <div class="crmd-section-title">${crmIcon('thermometer')} Termômetro</div>
    <div class="crmd-term-row">
      <div class="crmd-term-card quente">
        <div class="crmd-term-value">${fmtBRL(quenteValor)}</div>
        <div class="crmd-term-label">${crmIcon('fire')} Quente</div>
      </div>
      <div class="crmd-term-card morno">
        <div class="crmd-term-value">${fmtBRL(mornoValor)}</div>
        <div class="crmd-term-label">${crmIcon('cloud')} Morno</div>
      </div>
      <div class="crmd-term-card frio">
        <div class="crmd-term-value">${fmtBRL(frioValor)}</div>
        <div class="crmd-term-label">${crmIcon('snowflake')} Frio</div>
      </div>
    </div>

    <div style="display:flex; gap:28px; flex-wrap:wrap; margin-top:4px;">
      <div style="flex:1.4; min-width:300px;">
        <div class="crmd-section-title">${crmIcon('headset')} Últimas Calls</div>
        <div class="crmd-list-card">
          ${done.length === 0 ? `<div class="crmd-list-empty">Nenhuma call concluída ainda.</div>` : doneRowsHtml}
        </div>
      </div>
      <div style="flex:1; min-width:280px;">
        <div class="crmd-section-title">${crmIcon('calendar')} Próximas Calls</div>
        <div class="crmd-list-card" style="max-height:420px; overflow-y:auto;">
          ${upcoming.length === 0 ? `<div class="crmd-list-empty">Nenhuma reunião agendada ainda.</div>` : upcomingGroupedHtml}
        </div>
      </div>
    </div>

    <div class="crmd-section-title">${crmIcon('file-spreadsheet')} Diagnósticos criados</div>
    <div class="crmd-field" style="max-width:360px;">
      <input type="text" id="historyFilter" placeholder="Buscar por cliente ou empresa..." value="${escapeHtml(dashboardFilterText)}">
    </div>
    ${filtered.length === 0
      ? `<div class="crmd-list-card"><div class="crmd-list-empty">${list.length === 0 ? 'Nenhum diagnóstico criado ainda.' : 'Nenhum resultado para essa busca.'}</div></div>`
      : `<div class="crmd-list-card" style="overflow-x:auto;">
          <table class="crmd-table">
            <thead><tr><th>Perfil</th><th>Cliente</th><th>Empresa</th><th>Segmento</th><th>Data</th></tr></thead>
            <tbody>${diagRows}</tbody>
          </table>
        </div>`}
  `;

  return renderCrmShell('dashboard', content);
}

/* ---------------- History detail (read-only) ---------------- */
function finalDiagnosticInner(){
  const f = calcFinal();
  return `
    <div class="final-hero">
      <div class="eyebrow">O Giftback pode aumentar seu faturamento mensal em</div>
      <div class="big" style="font-size:56px; font-weight:800;">${fmtPct(f.giftbackPct)}</div>
      <div class="month-note">Com base no faturamento médio mensal informado de ${fmtBRL(state.faturamentoMensal)}.</div>
    </div>

    <div class="strategy-block">
      <div class="strategy-title">1) Estratégia Indicações</div>
      <p class="strategy-text">Usando a sua base de clientes de forma estratégica, você já pode levantar um incremento de <strong>${fmtBRL(f.ind.incrementoIndicacoes)}</strong> em faturamento de novas vendas e mais <strong>${fmtInt(f.ind.novosClientes)} novos clientes</strong> indicados da sua própria base.</p>
    </div>

    <div class="strategy-block">
      <div class="strategy-title">2) Giftback</div>
      <p class="strategy-text">É uma estratégia que tem como estimativa aumentar seu faturamento mensal atual em <strong>${fmtPct(f.giftbackPct)}</strong>. Dentro do cenário apresentado nesta simulação, estimamos um valor médio mensal de <strong>${fmtBRL(f.gb.faturamentoTotal)}</strong> e um acumulado de <strong>${fmtBRL(f.acumulado12Giftback)}</strong> em 12 meses.</p>
    </div>

    <div class="metric-card blue">
      <div class="eyebrow">Faturamento projetado · mês 1 → mês 2</div>
      <div class="from-to">
        <span class="from" style="color:#dbe9f7; text-decoration-color:#a9cbe8;">${fmtBRL(state.faturamentoMensal)}</span>
        <span class="arrow" style="color:#dbe9f7;">→</span>
        <span class="to">${fmtBRL(f.faturamentoMes2)}</span>
      </div>
      <div class="cap">+${fmtPct(f.pctAcrescimo)} combinando Indicações e Giftback num único mês de ação</div>
    </div>

    <div class="assumption">
      <strong>Como calculamos:</strong> o percentual em destaque é o faturamento total do Giftback dividido pelo faturamento médio mensal informado. O retorno do mês 1 soma o incremento do Programa de Indicações com o faturamento total do Giftback, e o faturamento do mês 2 é o faturamento atual mais esse incremento. A projeção de 12 meses considera apenas a repetição mensal da ação de Giftback — o Programa de Indicações tende a ter efeito não linear ao longo do tempo e não entra nessa conta.
    </div>

    <p class="disclaimer-note">Estes dados são uma estimativa, baseada nos dados informados na pesquisa, cruzados com dados de mercado, comportamento de utilização de clientes e estatísticas praticadas no mercado — não sendo números reais, mas uma simulação para um norte de onde podemos chegar com os resultados, a partir destas ações e solução.</p>
  `;
}

function renderHistoryDetail(){
  return `
    <div class="panel">
      <a href="#" class="back-link" id="backToDashboardFromHistory">← Painel</a>
      <h1>${escapeHtml(state.nomeEmpresa || 'Diagnóstico')}</h1>
      <p class="sub">${escapeHtml(currentProfile().name)} · ${escapeHtml(state.nomeCliente)} · ${escapeHtml(state.segmento)}${state.subSegmento ? ' · '+escapeHtml(state.subSegmento) : ''} · criado em ${fmtDatePt(appState.historyCreatedAt)}</p>
      ${finalDiagnosticInner()}
      <div class="actions">
        <button class="btn-ghost" id="backHist">Voltar ao painel</button>
        <button class="btn-primary" id="downloadPdfHist">Baixar PDF novamente</button>
      </div>
      <div style="display:flex; justify-content:flex-end; margin-top:10px;">
        <a id="pdfManualLink" class="manual-pdf-link" style="display:none;" download>Se o download não iniciar, clique aqui para abrir o PDF</a>
      </div>
    </div>
  `;
}

/* ---- Chat intake (step 0) ---- */
function renderChatStep(){
  const c = state.chat;
  const flow = currentFlow();
  if(c.transcript.length === 0 && !c.meetingStage){
    // Hero question (first turn of the profile's flow)
    const heroTurn = flow[0];
    return `
      <div class="chat-wrap">
        <div class="chat-hero-centered">
          <div class="chat-hero">
            <h1>${currentProfile().heroTitleHtml()}</h1>
          </div>
          <div class="chat-input-row">
            <div class="sparkle">${sparkleSVG()}</div>
            <div class="pill-wrap">
              <input type="text" id="chatInput" placeholder="${heroTurn.placeholder}" autocomplete="off">
              <button class="send-btn" id="chatSend" aria-label="Enviar">${arrowSVG()}</button>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  const thread = c.transcript.map(m=>{
    if(m.type==='ai') return `<div class="ai-block">${m.lines.map(l=>`<div class="ai-line">${l}</div>`).join('')}</div>`;
    if(m.type==='report') return renderChatReportCard(m.data);
    if(m.type==='curvecard') return renderChatCurveCard(m.data);
    if(m.type==='highlightstat') return `<div class="chat-highlight-stat">${m.html}</div>`;
    if(m.type==='combinedtable') return renderChatCombinedTable(m.data);
    if(m.type==='accumcard') return renderChatAccumCard(m.data);
    if(m.type==='finalsummary') return renderChatFinalSummary(m.data);
    if(m.type==='diagnostico4frentes') return renderChatDiagnostico4Frentes(m.data);
    if(m.type==='frente4card') return renderChatFrente4Card(m.data);
    if(m.type==='resumoCard') return renderChatResumoCard(m.data);
    if(m.type==='relatorioCard') return renderChatRelatorioCard(m.data);
    if(m.type==='pdfdownload') return `<a href="${m.url}" download="${escapeHtml(m.filename)}" class="chat-pdf-link">⬇ ${escapeHtml(m.label)} <span>${escapeHtml(m.filename)}</span></a>`;
    if(m.type==='whatsapplink') return `<a href="${m.url}" target="_blank" rel="noopener noreferrer" class="chat-whatsapp-link">Abrir link do WhatsApp</a>`;
    return `<div class="user-bubble">${m.text}</div>`;
  }).join('');

  let inputArea = '';
  if(c.typing){
    inputArea = `<div class="ai-block"><div class="typing-indicator"><span class="dot"></span><span class="dot"></span><span class="dot"></span></div></div>`;
  } else if(c.dor1ChatStage === 'askTicket'){
    inputArea = `
      <div class="chat-input-row">
        <div class="sparkle">${sparkleSVG()}</div>
        <div class="pill-wrap">
          <input type="text" id="chatInput" placeholder="Ex: R$ 220" autocomplete="off">
          <button class="send-btn" id="chatSend" aria-label="Enviar">${arrowSVG()}</button>
        </div>
      </div>
    `;
  } else if(c.dor1ChatStage === 'confirmGiftback'){
    inputArea = `
      <div class="confirm-row">
        <button class="btn-primary" id="dor1ConfirmGiftback">Sim, vamos para o Giftback!</button>
      </div>
    `;
  } else if(c.dor1ChatStage === 'giftbackForm'){
    inputArea = `
      <div class="chat-form-card">
        <div class="row2">
          <div class="field">
            <label>Valor do Giftback</label>
            <input type="text" inputmode="decimal" id="dor1GiftbackValor" value="${state.giftbackValor}" placeholder="Ex: 100">
          </div>
          <div class="field">
            <label>Compra mínima</label>
            <input type="text" inputmode="decimal" id="dor1CompraMinima" value="${state.compraMinima}" placeholder="Ex: 300">
          </div>
        </div>
        <p class="chat-form-tip">Legal destacarmos que, em média, o cliente consome <strong>4x</strong> o valor do Giftback — segundo estudos do mercado de quem já pratica.</p>
        <button class="btn-primary" id="dor1GiftbackNext">Próximo</button>
      </div>
    `;
  } else if(c.dor1ChatStage === 'confirmCombined'){
    inputArea = `
      <div class="confirm-row">
        <button class="btn-primary" id="dor1CombinedNext">Próximo</button>
      </div>
    `;
  } else if(c.dor1ChatStage === 'confirmFinalSummary'){
    inputArea = `
      <div class="confirm-row">
        <button class="btn-primary" id="dor1GenerateReportBtn">Gerar relatório do Diagnóstico em PDF</button>
      </div>
    `;
  } else if(c.dor1ChatStage === 'askWhatsapp'){
    inputArea = `
      <div class="chat-input-row">
        <div class="sparkle">${sparkleSVG()}</div>
        <div class="pill-wrap">
          <input type="text" id="chatInput" placeholder="Ex: (11) 99999-9999" autocomplete="off">
          <button class="send-btn" id="chatSend" aria-label="Enviar">${arrowSVG()}</button>
        </div>
      </div>
    `;
  } else if(c.meetingStage === 'segmento'){
    const options = meetingSegmentoOptions();
    const sel = c.multiSelectBuffer || [];
    const pills = options.map(s=>`<button class="segment-pill${sel.includes(s)?' active':''}" data-value="${escapeHtml(s)}">${escapeHtml(s)}</button>`).join('');
    inputArea = `
      <div class="segment-pills">${pills}</div>
      <div class="multiselect-footer">
        <span class="multiselect-count">${sel.length} selecionado${sel.length===1?'':'s'}</span>
        <button class="btn-primary" id="meetingSegmentoContinue" ${sel.length? '' : 'disabled'}>Continuar</button>
      </div>
    `;
  } else if(c.meetingStage === 'baseAtiva' || c.meetingStage === 'faturamento' || c.meetingStage === 'ticketMedio'){
    const placeholders = { baseAtiva:'Ex: 2.400', faturamento:'Ex: R$ 180.000', ticketMedio:'Ex: R$ 220' };
    inputArea = `
      <div class="chat-input-row">
        <div class="sparkle">${sparkleSVG()}</div>
        <div class="pill-wrap">
          <input type="text" id="chatInput" placeholder="${placeholders[c.meetingStage]}" autocomplete="off">
          <button class="send-btn" id="chatSend" aria-label="Enviar">${arrowSVG()}</button>
        </div>
      </div>
    `;
  } else if(c.meetingStage === 'objetivos'){
    const sel = c.multiSelectBuffer || [];
    const pills = OBJETIVO_OPTIONS.map(s=>`<button class="segment-pill${sel.includes(s)?' active':''}" data-value="${escapeHtml(s)}">${escapeHtml(s)}</button>`).join('');
    inputArea = `
      <div class="segment-pills">${pills}</div>
      <div class="multiselect-footer">
        <span class="multiselect-count">${sel.length} selecionado${sel.length===1?'':'s'}</span>
        <button class="btn-primary" id="meetingObjetivosContinue" ${sel.length? '' : 'disabled'}>Continuar</button>
      </div>
    `;
  } else if(c.meetingStage === 'confirmGenerate'){
    inputArea = `
      <div class="confirm-row">
        <button class="btn-primary" id="meetingGenerateBtn">Gerar diagnóstico inicial...</button>
      </div>
    `;
  } else if(c.dor1ChatStage === 'confirmSend'){
    inputArea = `
      <div class="confirm-row">
        <button class="btn-primary" id="dor1SendDiagnosticoBtn">Enviar diagnóstico...</button>
      </div>
    `;
  } else if(c.dor1ChatStage === 'confirmNextStage'){
    inputArea = `
      <div class="confirm-row">
        <button class="btn-primary" id="dor1NextStageBtn">Sim, vamos!</button>
      </div>
    `;
  } else if(c.awaitingConfirm){
    inputArea = `
      <div class="confirm-row">
        <button class="btn-primary" id="confirmBtn">Sim, favor gerar!</button>
      </div>
    `;
  } else if(c.noClientsBranch){
    // Ramo especial: negócio ainda sem clientes ativos — pede o objetivo de pré-lançamento.
    const pills = OBJETIVO_PRELANCAMENTO_OPTIONS.map(s=>`<button class="segment-pill singleselect-pill" data-preclients-value="${escapeHtml(s)}">${escapeHtml(s)}</button>`).join('');
    inputArea = `<div class="segment-pills">${pills}</div>`;
  } else if((isDor1() && c.dor1ChatStage) || c.meetingStage){
    // Estágio de transição (entre mensagens, sem ação disponível ainda).
    // Evita cair no fallback genérico abaixo, que re-renderizaria os pills/turn antigos do fluxo
    // de intake e permitiria clicar neles de novo por engano, reiniciando a narrativa.
    inputArea = '';
  } else {
    const turn = flow[c.fieldIndex];
    if(turn.type === 'pills' || turn.type === 'singleselect'){
      const cls = turn.type === 'singleselect' ? 'segment-pill singleselect-pill' : 'segment-pill';
      const pills = turn.options.map(s=>`<button class="${cls}" data-value="${escapeHtml(s)}">${escapeHtml(s)}</button>`).join('');
      inputArea = `<div class="segment-pills">${pills}</div>`;
    } else if(turn.type === 'multiselect'){
      const sel = c.multiSelectBuffer || [];
      const pills = turn.options.map(s=>`<button class="segment-pill${sel.includes(s)?' active':''}" data-value="${escapeHtml(s)}">${escapeHtml(s)}</button>`).join('');
      inputArea = `
        <div class="segment-pills">${pills}</div>
        <div class="multiselect-footer">
          <span class="multiselect-count">${sel.length}/${turn.max} selecionados</span>
          <button class="btn-primary" id="multiselectContinue" ${sel.length? '' : 'disabled'}>Continuar</button>
        </div>
      `;
    } else {
      inputArea = `
        <div class="chat-input-row">
          <div class="sparkle">${sparkleSVG()}</div>
          <div class="pill-wrap">
            <input type="text" id="chatInput" placeholder="${turn.placeholder||''}" autocomplete="off">
            <button class="send-btn" id="chatSend" aria-label="Enviar">${arrowSVG()}</button>
          </div>
        </div>
        ${turn.noClientsOption ? `
        <div class="no-clients-row">
          <button class="btn-ghost btn-sm" id="noClientsBtn">Ainda não tenho clientes, estou no início da operação</button>
        </div>` : ''}
      `;
    }
  }

  return `<div class="chat-wrap"><div class="chat-thread">${thread}</div>${inputArea}</div>`;
}

function pushAi(lines){ state.chat.transcript.push({type:'ai', lines: Array.isArray(lines)?lines:[lines]}); }
function pushUser(text){ state.chat.transcript.push({type:'user', text}); }

function proceedChat(userDisplayText, afterDelayFn){
  const c = state.chat;
  pushUser(userDisplayText);
  c.typing = true;
  render();
  const delay = 2000 + Math.random()*1000; // 2 a 3 segundos
  setTimeout(()=>{
    c.typing = false;
    afterDelayFn();
    render();
  }, delay);
}

/* Generic engine: works for text/number/currency/pills/singleselect/multiselect
   turns, driven by the active profile's `flow` definition. */
function parseTurnValue(turn, raw){
  if(turn.type === 'multiselect') return Array.isArray(raw) ? raw.slice() : [raw];
  if(turn.type === 'singleselect') return [String(raw).trim()];
  if(turn.type === 'text' || turn.type === 'pills') return String(raw).trim();
  if(turn.type === 'number' || turn.type === 'currency') return parseBRNumber(raw);
  return raw;
}
function isValidTurnValue(turn, val){
  if(turn.type === 'multiselect' || turn.type === 'singleselect') return Array.isArray(val) && val.length > 0;
  if(turn.type === 'number' || turn.type === 'currency') return !!val && val > 0;
  return !!val;
}
function displayForTurn(turn, val){
  if(turn.type === 'multiselect' || turn.type === 'singleselect') return val.join(', ');
  if(turn.displayAs === 'count') return fmtInt(val) + ' clientes';
  if(turn.displayAs === 'currency') return fmtBRL(val);
  return val;
}

function submitChatValue(rawValue){
  const c = state.chat;
  if(c.meetingStage === 'baseAtiva'){ submitMeetingBaseAtiva(rawValue); return; }
  if(c.meetingStage === 'faturamento'){ submitMeetingFaturamento(rawValue); return; }
  if(c.meetingStage === 'ticketMedio'){ submitMeetingTicketMedio(rawValue); return; }
  if(c.dor1ChatStage === 'askTicket'){
    submitDor1TicketMedio(rawValue);
    return;
  }
  if(c.dor1ChatStage === 'askWhatsapp'){
    submitDor1Whatsapp(rawValue);
    return;
  }
  answerCurrentTurn(rawValue);
}
function selectSegmento(value){
  answerCurrentTurn(value);
}
function toggleMultiselectOption(value){
  const c = state.chat;
  const flow = currentFlow();
  const turn = flow[c.fieldIndex];
  const buf = c.multiSelectBuffer;
  const idx = buf.indexOf(value);
  if(idx > -1){
    buf.splice(idx,1);
  } else if(buf.length < (turn.max || 3)){
    buf.push(value);
  }
  render();
}
function confirmMultiselect(){
  const c = state.chat;
  if(!c.multiSelectBuffer.length) return;
  const val = c.multiSelectBuffer.slice();
  c.multiSelectBuffer = [];
  answerCurrentTurn(val);
}

/* Special branch: negócio ainda sem clientes ativos.
   Ignora a pergunta de faturamento (sem clientes não há faturamento a reportar)
   e direciona para um objetivo específico de pré-lançamento. */
function startNoClientsBranch(){
  const c = state.chat;
  state.baseAtiva = 0;
  state.faturamentoMensal = 0;
  state.semClientes = true;
  proceedChat('Ainda não tenho clientes, estou no início da operação', ()=>{
    pushAi([`Entendo, ${state.nomeCliente}!`, 'Então você deve ter o objetivo de:']);
    c.noClientsBranch = true;
  });
}
function selectNoClientsObjetivo(value){
  const c = state.chat;
  state.objetivos = [value];
  proceedChat(value, ()=>{
    pushAi('Já temos o diagnóstico inicial, podemos prosseguir?');
    c.noClientsBranch = false;
    c.awaitingConfirm = true;
  });
}

function answerCurrentTurn(rawValue){
  const c = state.chat;
  const flow = currentFlow();
  const turnIndex = c.transcript.length === 0 ? 0 : c.fieldIndex;
  const turn = flow[turnIndex];
  if(!turn) return;

  const val = parseTurnValue(turn, rawValue);
  if(!isValidTurnValue(turn, val)) return;

  state[turn.field] = val;
  const displayText = displayForTurn(turn, val);

  proceedChat(displayText, ()=>{
    if(turn.terminal){
      if(isDor1()){
        startDor1ChatNarrative();
      } else {
        pushAi(turn.confirmMessage);
        c.awaitingConfirm = true;
      }
    } else {
      const aiLines = turn.onAnswered(val);
      pushAi(aiLines);
      c.fieldIndex = turnIndex + 1;
    }
  });
}

/* ---------------- Dor 1: diagnóstico apresentado dentro da própria conversa ---------------- */
function playAiSequence(blocks, onComplete){
  const c = state.chat;
  // Neutraliza qualquer estágio anterior (ex: um botão de confirmação já respondido)
  // para que, durante as pausas entre mensagens, nada clicável e desatualizado apareça.
  c.dor1ChatStage = 'narrating';
  function step(i){
    if(i >= blocks.length){ onComplete(); return; }
    c.typing = true;
    render();
    const delay = 1800 + Math.random()*900;
    setTimeout(()=>{
      c.typing = false;
      const block = blocks[i];
      if(block && typeof block === 'object' && !Array.isArray(block) && block.type){
        state.chat.transcript.push({type: block.type, data: block.data});
      } else {
        pushAi(block);
      }
      render();
      setTimeout(()=> step(i+1), 350);
    }, delay);
  }
  step(0);
}

