function diagnosticTitleInfo(){
  const obj = (state.objetivos && state.objetivos[0]) || '';
  const map = {
    'Vender mais': { title: 'Seu problema é vendas e trazer mais novos clientes.', solution: 'Giftback + Programa de Indicações' },
    'Clientes novos': { title: 'Seu problema é vendas e trazer mais novos clientes.', solution: 'Giftback + Programa de Indicações' },
    'Fidelizar meus clientes, não voltam': { title: 'Seu problema é na retenção: não criar estratégias e gatilhos para o cliente voltar.' },
    'Já são fidelizados, quero vender mais para eles': { title: 'Você tem uma base que já compra, mas está estagnada — falta criar motivos para comprar mais.' },
    'Vender com margem sem desconto': { title: 'Cansado de brigar por preço e dar desconto, não é?' },
    'Sair da briga de preço': { title: 'Cansado de brigar por preço e dar desconto, não é?' },
    'Não consigo gerar valor além de preço': { title: 'Cansado de brigar por preço e dar desconto, não é?' },
    'Estou iniciando, quero criar algo diferente': { title: 'Que legal! Você agora deve se destacar de quem já está no mercado... essa é a estratégia que vamos desenhar.', noPrefix:true }
  };
  OBJETIVO_PRELANCAMENTO_OPTIONS.forEach(o=>{ map[o] = map['Estou iniciando, quero criar algo diferente']; });
  return map[obj] || null;
}

